from html.parser import HTMLParser
from pathlib import Path
import pydot

class Scripts(HTMLParser):
    def __init__(self):
        super().__init__()
        self.active = False
        self.scripts = []
    def handle_starttag(self, tag, attrs):
        if tag == 'script':
            self.active = True
    def handle_endtag(self, tag):
        if tag == 'script':
            self.active = False
    def handle_data(self, data):
        if self.active and '.renderDot("'`'"' in data:
            self.scripts.append(data)

parser = Scripts()
parser.feed(Path('blueprint/web/dep_graph_document.html').read_text())
assert len(parser.scripts) == 1
source = parser.scripts[0].split('.renderDot("'`'"', 1)[1].split('"'`)'"', 1)[0]
graph, = pydot.graph_from_dot_data(source)
edges = [(edge.get_source().strip('\"'), edge.get_destination().strip('\"'))
         for edge in graph.get_edges()]
